@dataclass(frozen=True)
class ComplianceResult:
    compliant: bool
    violations: Tuple[str, ...]
    warnings: Tuple[str, ...]

class ConstitutionViolation(ValueError):
    pass

def required_route_for(level: ActionLevel) -> Tuple[str, ...]:
    if level <= ActionLevel.OBSERVE:
        return ()
    if level == ActionLevel.PREPARE:
        return ("constitutional_compliance_check",)
    if level == ActionLevel.PROPOSE:
        return ("constitutional_compliance_check", "governance_review")
    if level == ActionLevel.GOVERNED_WRITE:
        return (
            "constitutional_compliance_check", "governance_review",
            "human_review_gate", "approval_or_rejection",
            "controlled_execution_layer", "governed_execution_dispatcher",
        )
    return (
        "constitutional_compliance_check", "governance_review",
        "human_review_gate", "approval_or_rejection",
        "controlled_execution_layer", "governed_execution_dispatcher",
    )

def validate_action(contract: ActionContract) -> ComplianceResult:
    violations = []
    warnings = []
    if not contract.action_id.strip():
        violations.append("empty_action_id")
    if not contract.adapter.strip():
        violations.append("missing_adapter")
    if contract.direct_renderer_write:
        violations.append("renderer_direct_write_forbidden")
    if contract.arbitrary_code_execution:
        violations.append("arbitrary_code_execution_forbidden")
    required = required_route_for(contract.level)
    missing = tuple(item for item in required if item not in contract.governance_route)
    if missing:
        violations.append("governance_route_incomplete:" + ",".join(missing))
    if contract.level >= ActionLevel.GOVERNED_WRITE:
        if not contract.confirmation_required:
            violations.append("confirmation_required")
        if not contract.journal_required:
            violations.append("journal_required")
        if not contract.permissions:
            violations.append("permissions_required")
        if not contract.rollback_strategy:
            warnings.append("rollback_unavailable_must_be_explicitly_disclosed")
    if contract.level >= ActionLevel.IRREVERSIBLE_OR_EXTERNAL and contract.rollback_strategy:
        warnings.append("rollback_claim_must_be_empirically_verified")
    return ComplianceResult(not violations, tuple(violations), tuple(warnings))

def enforce_action(contract: ActionContract) -> None:
    result = validate_action(contract)
    if not result.compliant:
        raise ConstitutionViolation(";".join(result.violations))

def validate_epistemic_state(state: Mapping[str, Any]) -> ComplianceResult:
    violations = []
    for key, expected in EPISTEMIC_INVARIANTS.items():
        if state.get(key) is not expected:
            violations.append(f"epistemic_invariant:{key}")
    return ComplianceResult(not violations, tuple(violations), ())

def validate_role_separation(civilization_id: str, representative_id: str, interface_id: str) -> ComplianceResult:
    values = [civilization_id.strip(), representative_id.strip(), interface_id.strip()]
    violations = []
    if not all(values):
        violations.append("role_identifier_missing")
    if len(set(values)) != 3:
        violations.append("civilization_representative_interface_conflation")
    return ComplianceResult(not violations, tuple(violations), ())

